NAME = 'ACV: A Conservative Version'
BOOK = 'Song of Solomon'

CHAPTERS = {
    1: {
        1: 'Pesem pesmi, ki je Salomonova.',
        2: 'O da bi me poljubil z ust svojih poljubom! ker ljubezen tvoja je boljša nego vino.',
        3: 'Mazila tvoja sladko diše, ime tvoje je kakor izlito mazilo; zato te ljubijo device.',
        4: 'Vleci me, in pohitimo za teboj! Vpeljal me je kralj v hrame svoje: radovati se hočemo in v tebi veseliti, hvaliti čemo ljubezen tvojo bolj nego vino. Iskreno te ljubijo.',
        5: 'Črna sem, ali ljubka, o hčere jeruzalemske, kakor kedarski šatori, kakor Salomonovi zastori.',
        6: 'Ne glejte me, ker sem začrnela, ker me je sonce opalilo. Matere moje sinovi so se srdili z mano, postavili so me za varuhinjo v vinogradih – a vinograda, ki je moj, nisem varovala!',
        7: 'Povej mi, o ti, ki ga ljubi duša moja, kje paseš čredo svojo? kje ji daješ počivati opoldne? ker čemu naj bi bila kakor tavajoča pri čredah tovarišev tvojih?',
        8: 'Ako ne veš, o najlepša med ženami, pojdi ven, po stopinjah ovac, in pasi kozliče svoje pri prebivališčih pastirjev.',
        9: 'Konju pri krasnem vozu Faraonovem te primerjam, o prijateljica moja!',
        10: 'Ljubka so lica tvoja med verižicami, vrat tvoj z nizom biserov.',
        11: 'Naredimo ti verižice zlate s srebrnimi kroglicami.',
        12: 'Dokler je kralj sedel pri omizju svojem, je vonjala narda moja vonjavo svojo.',
        13: 'Ljubi moj mi je kitica mire, ki leži med mojimi prsmi.',
        14: 'Ljubi moj mi je šopek ciprovih cvetlic iz vinogradov v Engedi.',
        15: 'Glej, lepa si, prijateljica moja, glej, lepa si, oči tvoje so kakor golobice.',
        16: 'Glej, lep si, ljubi moj, da, ljubezniv, tudi najino ležišče je mlado zelenje.',
        17: 'Tramovje hiše najine je cedrovo in obložci najini cipresovi.',
    },
    2: {
        1: 'Jaz sem roža saronska, lilija v dolinah.',
        2: 'Kakor lilija med trnjem, tako je prijateljica moja med hčerami.',
        3: 'Kakor jablan med drevjem v gozdu, tako je ljubi moj med sinovi. V senci njegovi sem želela sedeti in sedim, in sad njegov je sladak grlu mojemu.',
        4: 'Vpeljal me je v hišo, kjer se gostujejo, in zastava njegova nad menoj je ljubezen.',
        5: 'Okrepčajte me z grozdnimi gručami, poživite me z jabolki, ker sem bolna od ljubezni!...',
        6: 'Levica njegova je pod glavo mojo in z desnico svojo me objema.',
        7: 'Rotim vas, hčere jeruzalemske, pri gazelah in pri košutah poljskih, da ne prebudite in ne predramite ljubezni, dokler ji je drago.',
        8: 'Glas ljubega svojega čujem! glej, on prihaja, skače po gorah, poskakuje po hribih.',
        9: 'Ljubi moj je podoben gazeli ali mlademu jelenu. Glej, stoji za našim zidom, gleda skozi okno, zre skozi omrežje.',
        10: 'Izpregovoril je ljubi moj in mi veli: „Vstani, prijateljica moja, lepa moja, in pridi ven!',
        11: 'Zakaj, glej, zima je minila, deževje je prešlo, konec mu je.',
        12: 'Cvetje se prikazuje po zemlji, čas petja je prišel, in grlice glas se sliši v deželi naši;',
        13: 'smokovec rumeni zarodke smokev svojih, in vinske trte poganjajo očesca in vonjajo duh svoj. Vstani, prijateljica moja, lepa moja, in pridi ven!',
        14: 'Golobica moja v razpoklinah pečevja, v skrivališču skalnih sten, daj, da vidim tvoj obraz, daj mi slišati svoj glas, ker glas tvoj je sladak in obraz tvoj miloviden.“',
        15: 'Polovite nam lisice, male lisice, ki kvarijo vinograde, zakaj naši vinogradi so v cvetu!',
        16: 'Ljubi moj je moj in jaz sem njegova; on pase čredo svojo med lilijami.',
        17: 'Ko se ohladi dan in sence zbeže, vrni se ljubi moj, in podoben bodi gazeli ali mlademu jelenu na razpokanih gorah.',
    },
    3: {
        1: 'Na ležišču svojem po noči sem iskala njega, ki ga ljubi duša moja; iskala sem ga, a nisem ga našla.',
        2: 'Rečem: Naj vstanem in prehodim mesto, po ulicah in po trgih hočem iskati njega, ki ga ljubi duša moja. Iskala sem ga, a nisem ga našla.',
        3: 'Zalotili so me stražarji, ki hodijo po mestu; vprašam jih: Ste ga li videli, ki ga ljubi duša moja?',
        4: 'Le malo sem prešla mimo njih, ko sem ga našla, ki ga ljubi duša moja. Prijela sem ga in ga nisem pustila, dokler ga nisem vpeljala v matere svoje hišo in v hram porodnice svoje.',
        5: 'Rotim vas, hčere jeruzalemske, pri gazelah in pri košutah poljskih, da ne prebudite in ne predramite ljubezni, dokler ji je drago!',
        6: 'Kdo je ona, ki prihaja gori iz puščave, podobna stebru dima, polna vonja mire in kadila, vsakršnega dišečega prahu trgovčevega?',
        7: 'Glejte tu, prenosna postelja Salomonova: šestdeset junakov okoli nje, izmed Izraelovih junakov!',
        8: 'Vsi znajo sukati meč, so vešči vojni; slednji ima meč ob bedru svojem zaradi strahu po noči.',
        9: 'Nosilnico krasno si je napravil kralj Salomon iz lesa libanonskega.',
        10: 'Stebre njene je naredil iz srebra, slonilo iz zlata, sedalo iz škrlata, znotraj pa je umetno vezena z ljubeznijo od hčera jeruzalemskih.',
        11: 'Pojdite ven, o hčere sionske, in glejte kralja Salomona v vencu, s katerim ga je ovenčala mati njegova v dan poroke njegove in v dan veselja njegovega srca.',
    },
    4: {
        1: 'Glej, lepa si, prijateljica moja, glej, lepa si; oči tvoje so kakor golobice za pajčolanom tvojim; lasje tvoji so kakor čreda koz, ki leže po strmini gore Gileadske.',
        2: 'Zobje tvoji so kakor čreda ostriženih ovčic, ki stopajo gori iz kopeli, katerih vsaka ima dvojčeti in nerodovitne ni med njimi nobene.',
        3: 'Ustne tvoje so kakor karmezinasta vrvica in usta tvoja so ljubka; kakor odrezan kos margaranovega jabolka so senca tvoja izza pajčolana tvojega.',
        4: 'Vrat tvoj je kakor stolp Davidov, ki je zgrajen za orožnico, na njem visi tisoč ščitov, vsi ščiti junakov.',
        5: 'Prsi tvoje so kakor dve srnici, dvojčeti gazelini, ki se paseta med lilijami.',
        6: 'Dokler se ohladi dan in sence zbeže, pojdem h gori mirovi in k hribu kadila.',
        7: 'Vsa si lepa, prijateljica moja, in madeža ni na tebi.',
        8: 'Z menoj doli z Libanona, nevesta moja, z menoj prideš z Libanona; z vrha Amane boš gledala doli, z vrha Senirja in Hermona, od ležišč levov, od gorá leopardov.',
        9: 'Obvladala si mi srce, sestra moja, nevesta, obvladala si mi srce z enim pogledom svojih oči, z eno verižico na vratu svojem.',
        10: 'Kako je lepa ljubav tvoja, sestra moja, nevesta! koliko boljša je ljubav tvoja nego vino in mazil tvojih duh boljši nego vseh dišav!',
        11: 'Z usten tvojih, nevesta, kaplja strd, med in mleko sta pod jezikom tvojim, in oblačil tvojih duh je kakor Libanona vonj.',
        12: 'Zaklenjen vrt je sestra moja, nevesta, zaklenjen vrelec, zapečaten studenec.',
        13: 'Mladike tvoje so margaranov gaj z žlahtnim sadjem, s ciprovim cvetjem in z nardovimi rastlinami,',
        14: 'narda in žafran, kolmež in sladka skorjica, z vsakršnim kadilnim drevjem, mira in lopatika z vsemi najboljšimi dišavami.',
        15: 'Ti si studenec na vrtu, vodnjak žive vode in potoki, ki teko od Libanona.',
        16: 'Vstani, severni veter, in pridi, jug, vej skozi moj vrt, da kapljajo njega dišave! Naj pride ljubi moj na vrt svoj in uživa sadove, njemu dragocene.',
    },
    5: {
        1: 'Prišel sem na vrt svoj, sestra moja, nevesta, trgal sem miro svojo in balzam svoj, jedel sem satovje svoje s svojim medom vred, pil sem vino svoje z mlekom svojim vred. Jejte, prijatelji, pijte in napijte se, ljubljeni!',
        2: 'Spala sem, ali moje srce je bedelo – v tem začujem glas! Ljubi moj trka: „Odpri mi, sestra moja, ljubav moja, golobica moja, popolna moja! Zakaj glava moja je polna rose, kodri moji nočnih srag.“',
        3: '„Slekla sem suknjo svojo, kako bi jo spet oblekla? umila sem si noge, kako bi jih zopet oblatila?“',
        4: 'Ljubi moj seže z roko skozi luknjo v durih, in srce mi vztrepeta zaradi njega.',
        5: 'Vstala sem, da odprem ljubemu svojemu, in z rok mi je kapljala mira in s prstov tekoča mira na držaj ključalnice.',
        6: 'Odprla sem ljubemu svojemu; ali ljubi moj se je bil obrnil in odšel. Duša mi je ušla za njim, ko je govoril. Iskala sem ga, a nisem ga našla, klicala sem ga, a ni mi odgovoril.',
        7: 'Zalotili so me stražarji, ki hodijo po mestu, zbili so me, ranili so me, varuhi na zidu so mi vzeli moje ogrinjalo.',
        8: 'Rotim vas, hčere jeruzalemske, ako najdete ljubega mojega, kaj mu povejte? Da sem bolna od ljubezni.',
        9: 'Kaj je tvoj ljubi mimo drugih ljubovnikov, o najlepša med ženami, kaj je tvoj ljubi mimo drugih ljubovnikov, da nas tako rotiš?',
        10: 'Moj ljubi je bel in rdeč, odličnik med desetimi tisoči.',
        11: 'Glava njegova je kakor najčistejše zlato, kodri njegovi so valoviti, črni kakor vran.',
        12: 'Oči njegove so kakor golobice ob bistrih potokih, z mlekom umite, lepo posajene.',
        13: 'Lica njegova so kakor grede balzama, kakor lehe dišečih rastlin; usta njegova kakor lilije, s katerih kaplja tekoča mira.',
        14: 'Roke njegove so kakor valjci zlati, obloženi s topazi, telo njegovo kakor umotvor iz slonove kosti, pokrit s safiri.',
        15: 'Goleni njegove so kakor marmornati stebri, postavljeni na podstavkih iz čistega zlata, rast njegova kakor Libanon, odličen je kakor cedre.',
        16: 'Usta njegova so sladka in ves je ljubezniv. Tak je ljubi moj, tak je prijatelj moj, o hčere jeruzalemske!',
    },
    6: {
        1: 'Kam je šel ljubi tvoj, o najlepša med ženami, kam se je obrnil ljubi tvoj? Iskati ga hočemo s teboj!',
        2: 'Ljubi moj je šel doli na vrt svoj, h gredicam balzamovim, da bi pasel po vrtih in trgal lilije.',
        3: 'Jaz sem ljubega svojega in ljubi moj je moj, on pase čredo svojo med lilijami.',
        4: 'Lepa si, prijateljica moja, kakor Tirza, milovidna kakor Jeruzalem, strašna kakor vojske z zastavami.',
        5: 'Obrni oči od mene, ker me premagujejo. Lasje tvoji so kakor čreda koz, ki ležé po strmini Gileadski.',
        6: 'Zobje tvoji so kakor čreda ovac, ki stopajo gori iz kopeli, katerih vsaka ima dvojčeti in nerodovitne ni med njimi nobene.',
        7: 'Senca tvoja so kakor odrezan kos margaranovega jabolka za pajčolanom tvojim.',
        8: 'Šestdeset je kraljic in osemdeset priležnic in mladenk brez števila.',
        9: 'A edina je golobica moja, popolna moja; edinica je materi svoji, izvoljenka porodnici svoji. Hčere so jo videle in so jo blagorovale, tudi kraljice in priležnice in so jo hvalile.',
        10: 'Kdo je ona, ki prisvitava kakor jutranja zarja, lepa kakor mesec, čista kakor sonce, strašna kakor vojske z zastavami?',
        11: 'Šel sem doli na orehov vrt, da si ogledam zelene mladike v dolini, da pogledam, če dela vinska trta popke, če cveto margaranova jabolka.',
        12: 'A preden sem zaznal, me je posadila duša moja na krasni voz mojega plemenitega ljudstva.',
        13: 'Vrni se, vrni se, o Šulamljanka, vrni se, vrni se, da te bomo gledali! [6:14] Kaj hočete gledati Šulamljanko? kakor ples mahanaimski...',
    },
    7: {
        1: 'Kako lepe so noge tvoje v opankah, o knežja hči! Pregibi tvojega bedra so kakor nakitne verižice, rok umetnikovih delo.',
        2: 'Popek tvoj je kakor lepo okrogla čašica, v kateri ne manjka mešanega vina; život tvoj je kakor kup pšenice, z lilijami obtaknjen.',
        3: 'Prsi tvoje so kakor dve srnici, dvojčeti gazelini.',
        4: 'Vrat tvoj je podoben stolpu iz slonove kosti, oči tvoje so kakor ribniki v Hesbonu, pri vratih ljudnatega mesta; nos tvoj kakor libanonski stolp, ki gleda proti Damasku.',
        5: 'Glava tvoja na tebi je podobna Karmelu, in lasje glave tvoje so kakor škrlat: kralj je v sponah kodrov tvojih.',
        6: 'Kako si ti lepa in mila, o ljubav, med vsemi radostmi!',
        7: 'Ta rast tvoja je podobna palmovemu drevesu in prsi tvoje grozdom.',
        8: 'Dejal sem: Zlesti hočem na palmovo drevo in prijeti za njegove mladice; in naj mi bodo prsi tvoje kakor grozdje na vinski trti in tvojega diha vonj kakor jabolka',
        9: 'in usta tvoja kakor najboljše vino... Ki mojemu ljubemu gladko teče, ki daje govor ustom spečih.',
        10: 'Jaz sem ljubega svojega, in poželenje njegovo je po meni.',
        11: 'Pridi, ljubi moj, pojdiva ven na polje, prenočujva v vaseh.',
        12: 'Zgodaj vstaneva in pojdiva k vinogradom, poglejva, če dela vinska trta popke in če se njen cvet odpira in če cveto margaranove jablani: tam ti dam ljubezni svoje.',
        13: 'Ljubezenska jabolčka vonjajo svoj vonj in nad našimi durmi je vsakršnega sadja, novega in starega, ki sem ga prihranila tebi, ljubi moj.',
    },
    8: {
        1: 'O da bi bil kakor moj brat, ki je sesal prsi matere moje! Ako bi te zalotila zunaj, bi te poljubila, in nihče bi me ne smel zaničevati.',
        2: 'Peljala bi te, privedla te v matere svoje hišo, ti bi me poučeval; jaz bi te napajala z dišečim vinom, s sokom svojih margaranovih jabolk.',
        3: 'Levica njegova je pod glavo mojo in z desnico svojo me objema.',
        4: 'Rotim vas, hčere jeruzalemske, da ne prebudite in ne predramite ljubezni, dokler ji je drago!',
        5: 'Kdo je ta, ki prihaja sem od puščave in se naslanja na ljubega svojega? Pod jablano sem te zbudil k ljubezni. Tam je bila v bolečinah s teboj mati tvoja, tam je trpela bolečine porodnica tvoja.',
        6: 'Deni me kakor pečat na srce svoje, kakor pečat na ramo svojo! Kajti ljubezen je silna kakor smrt, njena gorečnost trdna [Ali: stanovitna.] kakor grob; kakor grob; njen žar je žar ognja, plamen Gospodov.',
        7: 'Velike vode ne morejo ugasiti ljubezni, ne reke je poplaviti. Ako bi hotel kdo dati vse imetje hiše svoje za ljubezen, le zaničevanje bi dobil!',
        8: 'Sestro imamo, majhno, ki še nima prsi: kaj bomo storili s sestro svojo v dan, ko jo bodo snubili?',
        9: 'Ako je zid, zgradimo na njej srebrn nadzidek v utrdbo; ako je ona duri, ogradimo jo z deskami cedrovimi.',
        10: 'Jaz sem zid, in prsi moje so kakor stolpi. Tedaj sem bila v očeh njegovih kakor ona, ki je našla mir.',
        11: 'Salomon je imel vinograd v Baal-hamonu; izročil je vinograd varuhom, da bi vsakteri prinesel za njegov sad tisoč srebrnikov.',
        12: 'Moj vinograd, ki je meni izročen, je pred menoj; tisoč bodi tebi, o Salomon, in dvesto varuhom sadov njegovih.',
        13: 'Ti, ki prebivaš na vrtih, tovariši poslušajo glas tvoj; daj mi ga slišati!',
        14: 'Híti, ljubi moj, in bodi podoben gazeli ali mlademu jelenu v gorah balzamovih!',
    },
}
